package engine

import (
	"bytes"
	"encoding/binary"
	"net"
	"os"
	"path/filepath"
	"testing"

	"go.peanball.net/cap/internal/match"
	"go.peanball.net/cap/internal/pcap"
	"go.peanball.net/cap/internal/testgenpcap"
)

const (
	ethLen     = testgenpcap.EthHdrLen // bytes of Ethernet header before the L3 payload
	typeOffset = 12                    // EtherType word (last 2 bytes of Ethernet header)
	tcpOffset  = ethLen + testgenpcap.IPv4HdrLen
)

// loadFixture reads name out of testdata/ (generated by `go run ./test`,
// drift-pinned in internal/testgenpcap) and returns its records.
func loadFixture(t *testing.T, name string) []pcap.Record {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read testdata/%s: %v (run `go run ./test`)", name, err)
	}
	recs, err := testgenpcap.ReadAll(raw)
	if err != nil {
		t.Fatalf("parse testdata/%s: %v", name, err)
	}
	return recs
}

// readOut parses the engine's pcap output into link frames.
func readOut(t *testing.T, out []byte) [][]byte {
	t.Helper()
	rdr, err := pcap.NewReader(bytes.NewReader(out))
	if err != nil {
		t.Fatalf("read out: %v", err)
	}
	var frames [][]byte
	for {
		rec, err := rdr.Record()
		if err != nil {
			return frames
		}
		cp := make([]byte, len(rec.Data)) // Record aliases an internal buffer
		copy(cp, rec.Data)
		frames = append(frames, cp)
	}
}

func runEngineOn(t *testing.T, cfg Config, records []pcap.Record) (out bytes.Buffer, s Stats) {
	t.Helper()
	wr := pcap.NewWriterRaw(&out, pcap.LinkEthernet, 65535, false)
	eng, err := New(cfg, wr)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	for _, r := range records {
		if err := eng.Process(pcap.LinkEthernet, r.Timestamp, r.Data); err != nil {
			t.Fatalf("Process: %v", err)
		}
	}
	eng.Close()
	return out, eng.Stats()
}

// TestTunnelUnpackDuplicates verifies --unpack emits, for each kept outer
// v6-in-v4 packet, the verbatim outer frame followed by the inner packet
// reframed onto the outer link (testdata/unpack_4in6.pcap).
func TestTunnelUnpackDuplicates(t *testing.T) {
	recs := loadFixture(t, "unpack_4in6.pcap")

	m, err := match.NewSNI([]string{"inner.example"})
	if err != nil {
		t.Fatal(err)
	}
	offOut, offStats := runEngineOn(t, Config{Matcher: m}, recs)
	onOut, onStats := runEngineOn(t, Config{Matcher: m, Unpack: true}, recs)
	if offStats.PacketsOut != uint64(len(recs)) {
		t.Fatalf("Unpack off: %d of %d packets out", offStats.PacketsOut, len(recs))
	}
	if onStats.PacketsOut != uint64(2*len(recs)) {
		t.Fatalf("Unpack on: %d packets out, want %d (one dup per outer)", onStats.PacketsOut, 2*len(recs))
	}

	frames := readOut(t, onOut.Bytes())
	// Every second frame must be a dup: link header and MACs from outer,
	// protocol field rewritten to IPv4, payload is the inner packet. In a
	// 4-in-6 dup the outer frame carries Eth+IPv6+IPv4... so the inner IPv4
	// starts at dup[ethLen:] and outer's at outer[ethLen+IPv6HdrLen:].
	for i := 1; i < len(frames); i += 2 {
		outer, dup := frames[i-1], frames[i]
		if !bytes.Equal(dup[:typeOffset], outer[:typeOffset]) {
			t.Errorf("dup %d lost outer link header MACs", i)
		}
		if got := binary.BigEndian.Uint16(dup[typeOffset:ethLen]); got != 0x0800 {
			t.Errorf("dup %d protocol field = 0x%04x, want 0x0800", i, got)
		}
		if !bytes.Equal(dup[ethLen:], outer[ethLen+testgenpcap.IPv6HdrLen:]) {
			t.Errorf("dup %d payload != inner IPv4 packet", i)
		}
	}
	frames = readOut(t, offOut.Bytes())
	for i, fr := range frames {
		if got := binary.BigEndian.Uint16(fr[typeOffset:ethLen]); got != 0x86dd {
			t.Errorf("Unpack off: frame %d protocol field = 0x%04x, want 0x86dd (outer only)", i, got)
		}
	}
}

// TestTunnelUnpack6in6 is TestTunnelUnpackDuplicates for a nested-IPv6
// tunnel (testdata/unpack_6in6.pcap): the dup's protocol field is 0x86dd
// and its payload the inner IPv6 packet.
func TestTunnelUnpack6in6(t *testing.T) {
	recs := loadFixture(t, "unpack_6in6.pcap")

	m, err := match.NewSNI([]string{"inner.example"})
	if err != nil {
		t.Fatal(err)
	}
	offOut, offStats := runEngineOn(t, Config{Matcher: m}, recs)
	onOut, onStats := runEngineOn(t, Config{Matcher: m, Unpack: true}, recs)
	if offStats.PacketsOut != uint64(len(recs)) {
		t.Fatalf("Unpack off: %d of %d packets out", offStats.PacketsOut, len(recs))
	}
	if onStats.PacketsOut != uint64(2*len(recs)) {
		t.Fatalf("Unpack on: %d packets out, want %d (one dup per outer)", onStats.PacketsOut, 2*len(recs))
	}

	frames := readOut(t, onOut.Bytes())
	for i := 1; i < len(frames); i += 2 {
		outer, dup := frames[i-1], frames[i]
		if !bytes.Equal(dup[:typeOffset], outer[:typeOffset]) {
			t.Errorf("dup %d lost outer link header MACs", i)
		}
		if got := binary.BigEndian.Uint16(dup[typeOffset:ethLen]); got != 0x86dd {
			t.Errorf("dup %d protocol field = 0x%04x, want 0x86dd", i, got)
		}
		if !bytes.Equal(dup[ethLen:], outer[ethLen+testgenpcap.IPv6HdrLen:]) {
			t.Errorf("dup %d payload != inner IPv6 packet", i)
		}
	}
	frames = readOut(t, offOut.Bytes())
	for i, fr := range frames {
		if got := binary.BigEndian.Uint16(fr[typeOffset:ethLen]); got != 0x86dd {
			t.Errorf("Unpack off: frame %d protocol field = 0x%04x, want 0x86dd (outer only)", i, got)
		}
		// Inner starts past Eth+outer IPv6; high nibble is the version.
		if fr[ethLen+testgenpcap.IPv6HdrLen]>>4 != 6 {
			t.Errorf("Unpack off: frame %d inner version = %d, want 6", i, fr[ethLen+testgenpcap.IPv6HdrLen]>>4)
		}
	}
}

// TestProxyUnpackRewritesTuple: a kept connection whose client sends a PROXY
// v1 line gets, for every data packet after the header, a copy on the header
// tuple; header packets stay verbatim and get no copy.
// (testdata/unpack_proxy_rewrite.pcap.)
func TestProxyUnpackRewritesTuple(t *testing.T) {
	recs := loadFixture(t, "unpack_proxy_rewrite.pcap")

	m, err := match.NewSNI([]string{"x"}) // never matches; PROXY matcher does.
	if err != nil {
		t.Fatal(err)
	}
	pm := match.NewProxy(1, nil, nil) // v1, presence-only
	ord := match.Or{m, pm}

	_, offStats := runEngineOn(t, Config{Matcher: ord}, recs)
	onOut, onStats := runEngineOn(t, Config{Matcher: ord, Unpack: true}, recs)

	if offStats.PacketsOut != uint64(len(recs)) {
		t.Fatalf("off: %d packets out, want %d (verbatim)", offStats.PacketsOut, len(recs))
	}
	// Expected dups: server→client data packet, and the client→server data
	// packet after the header. The header packet gets no dup.
	want := len(recs) + 2
	if int(onStats.PacketsOut) != want {
		t.Fatalf("on: %d packets out, want %d", onStats.PacketsOut, want)
	}
	frames := readOut(t, onOut.Bytes())
	seen := 0
	for _, fr := range frames {
		ip := fr[ethLen:]
		if ip[0]>>4 != 4 { // only the PROXY-rewritten dups are IPv4
			continue
		}
		s := net.IP(ip[12:16]).String()          // v4 src
		d := net.IP(ip[16:20]).String()          // v4 dst
		sp := binary.BigEndian.Uint16(ip[20:22]) // v4 src port (into TCP)
		if s == "203.0.113.7" && d == "192.0.2.1" && sp == 41234 {
			seen++ // client→server rewritten
		}
		if s == "192.0.2.1" && d == "203.0.113.7" {
			seen++ // server→client rewritten
		}
	}
	if seen != 2 {
		t.Errorf("found %d PROXY-rewritten packets, want 2", seen)
	}
}
